{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/parts/bar-chart.json
    A row of vertical bars (sales by day, orders by week) with a caption under each bar. The chart is one image for assistive technology: `label` carries the summary, the bar values are in the captions and titles.
    Props (p): bars, label, max, height, className. *}
{var $v_bars = ($p['bars'] ?? null)}
{var $v_label = ($p['label'] ?? null)}
{var $v_max = ($p['max'] ?? null)}
{var $v_height = ($p['height'] ?? 160)}
{var $v_top = ui_max([1, ui_coalesce([$v_max, ui_max_by($v_bars, 'value')])])}
{capture $c_6}
  {capture $c_2}
    {foreach ui_l($v_bars) as $v_b}
      {capture $c_1}
        {=ui_include('ui/box/box.latte', ['p' => ['Class' => ui_s(ui_cnv(['w-full rounded', (ui_t(ui_get($v_b, ['muted'])) ? 'bg-muted-foreground' : 'bg-primary')])), 'Attrs' => ui_attrs(['style', ui_css(['height', ui_max([2, ui_round(ui_mul(ui_div(ui_get($v_b, ['value']), $v_top), 100))]), '%']), 'data-bar', ui_get($v_b, ['id'])])]])|noescape}
      {/capture}
      {=ui_include('ui/box/box.latte', ['p' => ['Class' => 'flex h-full min-w-0 flex-1 items-end', 'Attrs' => ui_attrs(['title', ui_coalesce([ui_get($v_b, ['title']), ui_get($v_b, ['label'])])])], 'children' => $c_1])|noescape}
    {/foreach}
  {/capture}
  {=ui_include('ui/box/box.latte', ['p' => ['Class' => 'flex min-w-0 items-end gap-2', 'Attrs' => ui_attrs(['role', 'img', 'aria-label', $v_label, 'style', ui_css(['height', $v_height, 'px'])])], 'children' => $c_2])|noescape}
  {capture $c_5}
    {foreach ui_l($v_bars) as $v_b}
      {capture $c_4}
        {capture $c_3}
          {=ui_text(ui_get($v_b, ['label']))}
        {/capture}
        {=ui_include('ui/text/text.latte', ['p' => ['Class' => 'absolute left-1/2 top-0 m-0 -translate-x-1/2 whitespace-nowrap text-xs font-medium text-muted-foreground'], 'children' => $c_3])|noescape}
      {/capture}
      {=ui_include('ui/box/box.latte', ['p' => ['Class' => 'relative h-4 min-w-0 flex-1'], 'children' => $c_4])|noescape}
    {/foreach}
  {/capture}
  {=ui_include('ui/box/box.latte', ['p' => ['Class' => 'mt-2 flex min-w-0 gap-2', 'Attrs' => ui_attrs(['aria-hidden', 'true'])], 'children' => $c_5])|noescape}
{/capture}
{=ui_include('ui/box/box.latte', ['p' => ['Class' => ui_s(ui_cnv(['min-w-0', ($p['className'] ?? '')])), 'Attrs' => ui_attrs(['data-slot', 'bar-chart'])], 'children' => $c_6])|noescape}
